use super::*;
use crate::workspace::{append,id};
use serde_json::json;

fn planning()->Value{json!({"schemaVersion":1,"fields":[],"records":[{"id":"world-person","kind":"character","name":"نور 明 e\u{301}","notes":"مِ 👩🏽‍🚀 𠀀 \u{e000}","aliases":[],"values":{},"links":[]}],"plotPoints":[],"facts":[],"boards":[],"lanes":[],"events":[],"constraints":[],"issues":[]})}
async fn fixture()->(tempfile::TempDir,Storage,Project,crate::UniverseNovelCreated){let dir=tempfile::tempdir().unwrap();let store=Storage::open(&dir.path().join("universe.sqlite")).await.unwrap();let root=store.create_universe("العالم 世界").await.unwrap();let initial=store.load_project_data(&root.id,"universeCatalogue").await.unwrap().unwrap();let payload=json!({"schemaVersion":1,"series":[{"id":"series","title":"سلسلة e\u{301} 𠀀"}],"novels":[]});let cat=store.save_project_data(&root.id,"universeCatalogue",payload,Some(initial.revision_id)).await.unwrap();let novel=store.create_universe_novel(&root.id,Some("series".into()),"Novel 中文",&cat.revision_id).await.unwrap();(dir,store,root,novel)}

#[tokio::test]
async fn catalogue_and_shared_notes_keep_checked_source_identity_and_never_copy_canon(){
    let (_dir,store,root,novel)=fixture().await;let world=store.save_project_data(&root.id,"planning",planning(),None).await.unwrap();let scene=store.load_scene(&novel.scene.id).await.unwrap();let cursor:i64=sqlx::query_scalar("SELECT count(*) FROM revision_envelope").fetch_one(&store.pool).await.unwrap();let snapshot=store.universe_catalogue_snapshot().await.unwrap();let member=snapshot.memberships.iter().find(|m|m.project_id==novel.project.id).unwrap();assert_eq!(member.status,"member");assert_eq!(member.universe_id.as_deref(),Some(root.id.as_str()));assert_eq!(member.series_id.as_deref(),Some("series"));let source=snapshot.universes.iter().find(|u|u.project_id==root.id).unwrap();assert_eq!(source.title,root.title);assert_eq!(source.catalogue_revision_id.as_deref(),Some(novel.catalogue_revision_id.as_str()));
    let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert_eq!(notes.membership,*member);assert_eq!(notes.planning,Some(world));assert!(notes.unavailable.is_none());assert_eq!(notes.universe,Some(source.clone()));assert!(store.load_project_data(&novel.project.id,"planning").await.unwrap().is_none());assert_eq!(store.load_scene(&novel.scene.id).await.unwrap(),scene);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM revision_envelope").fetch_one(&store.pool).await.unwrap(),cursor);let direct=store.universe_notes_snapshot(&root.id).await.unwrap();assert_eq!(direct.membership.status,"universe");assert_eq!(direct.universe.unwrap().project_id,root.id);
}
#[tokio::test]
async fn competing_catalogue_heads_and_duplicate_universe_claims_never_pick_a_group(){
    let (_dir,store,root,novel)=fixture().await;let current=store.load_project_data(&root.id,"universeCatalogue").await.unwrap().unwrap();let sibling=store.create_universe("Other world").await.unwrap();let sibling_head=store.load_project_data(&sibling.id,"universeCatalogue").await.unwrap().unwrap();let mut duplicate=sibling_head.payload;duplicate["novels"]=json!([{"projectId":novel.project.id,"seriesId":null}]);let mut tx=store.pool.begin().await.unwrap();let rid=id();append(&mut tx,&sibling.id,&format!("{}:universeCatalogue",sibling.id),"projectData",vec![sibling_head.revision_id],duplicate,"universeCatalogue",&rid).await.unwrap();sqlx::query("UPDATE project_data SET head=? WHERE project_id=? AND kind='universeCatalogue'").bind(&rid).bind(&sibling.id).execute(&mut *tx).await.unwrap();tx.commit().await.unwrap();let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert_eq!(notes.membership.status,"conflicted");assert!(notes.universe.is_none());assert!(notes.planning.is_none());assert!(notes.unavailable.unwrap().contains("Competing universes"));
    // Distinct leaves within one universe also refuse even if one projection
    // remains locally selected. Both saved alternatives are retained.
    let mut tx=store.pool.begin().await.unwrap();append(&mut tx,&root.id,&format!("{}:universeCatalogue",root.id),"projectData",vec![],current.payload,"universeCatalogue",&id()).await.unwrap();tx.commit().await.unwrap();let catalogue=store.universe_catalogue_snapshot().await.unwrap();let view=catalogue.universes.iter().find(|v|v.project_id==root.id).unwrap();assert!(view.catalogue.is_none());assert!(view.catalogue_revision_id.is_none());assert!(view.unavailable.as_ref().unwrap().contains("competing"));
}
#[tokio::test]
async fn corrupted_catalogue_ancestor_withholds_membership_instead_of_treating_novels_as_unassigned(){
    for defect in ["checksum","schema","parent","cycle","operation"]{let (_dir,store,root,novel)=fixture().await;let rows:Vec<String>=sqlx::query_scalar("SELECT id FROM revision_envelope WHERE project_id=? AND operation='universeCatalogue' ORDER BY rowid").bind(&root.id).fetch_all(&store.pool).await.unwrap();// Synthetic corruption fixture only; production revisions remain immutable.
        sqlx::query("DROP TRIGGER immutable_revision_update").execute(&store.pool).await.unwrap();let first=&rows[0];match defect{"checksum"=>{sqlx::query("UPDATE revision_envelope SET checksum='wrong' WHERE id=?").bind(first).execute(&store.pool).await.unwrap();},"schema"=>{sqlx::query("UPDATE revision_envelope SET schema_version=2 WHERE id=?").bind(first).execute(&store.pool).await.unwrap();},"operation"=>{sqlx::query("UPDATE revision_envelope SET operation='planning' WHERE id=?").bind(first).execute(&store.pool).await.unwrap();},_=>{let parent=if defect=="cycle"{rows.last().unwrap().clone()}else{"missing-parent".into()};sqlx::query("UPDATE revision_envelope SET parents=? WHERE id=?").bind(json!([parent]).to_string()).bind(first).execute(&store.pool).await.unwrap();}}
        let snapshot=store.universe_catalogue_snapshot().await.unwrap();let membership=snapshot.memberships.iter().find(|m|m.project_id==novel.project.id).unwrap();assert_eq!(membership.status,"unavailable","{defect}");assert!(membership.universe_id.is_none());let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert!(notes.planning.is_none());assert!(notes.universe.is_none());assert!(notes.unavailable.is_some());
    }
}
#[tokio::test]
async fn conflicted_or_corrupted_shared_planning_keeps_membership_but_withholds_notes(){
    let (_dir,store,root,novel)=fixture().await;let first=store.save_project_data(&root.id,"planning",planning(),None).await.unwrap();let second=store.save_project_data(&root.id,"planning",planning(),Some(first.revision_id.clone())).await.unwrap();sqlx::query("DROP TRIGGER immutable_revision_update").execute(&store.pool).await.unwrap();sqlx::query("UPDATE revision_envelope SET checksum='wrong' WHERE id=?").bind(&first.revision_id).execute(&store.pool).await.unwrap();let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert_eq!(notes.membership.status,"member");assert!(notes.planning.is_none());assert!(notes.unavailable.unwrap().contains("checksum"));sqlx::query("UPDATE revision_envelope SET checksum=? WHERE id=?").bind(hash(planning().to_string().as_bytes())).bind(&first.revision_id).execute(&store.pool).await.unwrap();
    let mut tx=store.pool.begin().await.unwrap();append(&mut tx,&root.id,&format!("{}:planning",root.id),"projectData",vec![first.revision_id],planning(),"planning",&id()).await.unwrap();tx.commit().await.unwrap();let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert!(notes.planning.is_none());assert!(notes.unavailable.unwrap().contains("competing"));assert_eq!(store.load_project_data(&root.id,"planning").await.unwrap().unwrap().revision_id,second.revision_id);
}
#[tokio::test]
async fn absent_membership_and_unavailable_catalogue_novels_are_explicit(){
    let (_dir,store,root,novel)=fixture().await;let standalone=store.create_novel("Standalone").await.unwrap();let notes=store.universe_notes_snapshot(&standalone.project.id).await.unwrap();assert_eq!(notes.membership.status,"unassigned");assert!(notes.unavailable.unwrap().contains("no assigned"));let current=store.load_project_data(&root.id,"universeCatalogue").await.unwrap().unwrap();let mut payload=current.payload;payload["novels"].as_array_mut().unwrap().push(json!({"projectId":"not-on-this-computer","seriesId":null}));let mut tx=store.pool.begin().await.unwrap();let rid=id();append(&mut tx,&root.id,&format!("{}:universeCatalogue",root.id),"projectData",vec![current.revision_id],payload,"universeCatalogue",&rid).await.unwrap();sqlx::query("UPDATE project_data SET head=? WHERE project_id=? AND kind='universeCatalogue'").bind(&rid).bind(&root.id).execute(&mut *tx).await.unwrap();tx.commit().await.unwrap();let snapshot=store.universe_catalogue_snapshot().await.unwrap();let view=snapshot.universes.iter().find(|u|u.project_id==root.id).unwrap();assert!(view.catalogue.as_ref().unwrap().novels.iter().any(|n|n.project_id=="not-on-this-computer"));assert_eq!(snapshot.memberships.iter().find(|m|m.project_id==novel.project.id).unwrap().status,"member");assert!(store.universe_notes_snapshot("not-on-this-computer").await.unwrap_err().contains("not available"));
}
#[tokio::test]
async fn retained_title_conflicts_and_stale_projection_do_not_choose_shared_notes(){
    let (_dir,store,root,novel)=fixture().await;let mut tx=store.pool.begin().await.unwrap();append(&mut tx,&root.id,&root.id,"project",vec![],json!({"title":"Other title","order":[]}),"create",&id()).await.unwrap();tx.commit().await.unwrap();let snapshot=store.universe_catalogue_snapshot().await.unwrap();let view=snapshot.universes.iter().find(|u|u.project_id==root.id).unwrap();assert!(view.catalogue.is_none());assert!(view.unavailable.as_ref().unwrap().contains("title"));assert!(store.universe_notes_snapshot(&novel.project.id).await.unwrap().planning.is_none());
    let (_dir,store,root,novel)=fixture().await;sqlx::query("UPDATE project_data SET head=(SELECT id FROM revision_envelope WHERE project_id=? AND operation='universeCatalogue' ORDER BY rowid LIMIT 1) WHERE project_id=? AND kind='universeCatalogue'").bind(&root.id).bind(&root.id).execute(&store.pool).await.unwrap();let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert!(notes.planning.is_none());assert_eq!(notes.membership.status,"conflicted");
}
#[tokio::test]
async fn missing_universe_title_ancestor_does_not_hide_behind_valid_catalogue_history(){
    let (_dir,store,root,novel)=fixture().await;let head:String=sqlx::query_scalar("SELECT id FROM revision_envelope WHERE project_id=? AND entity_type='project' LIMIT 1").bind(&root.id).fetch_one(&store.pool).await.unwrap();sqlx::query("DROP TRIGGER immutable_revision_update").execute(&store.pool).await.unwrap();sqlx::query("UPDATE revision_envelope SET parents=? WHERE id=?").bind(json!(["missing-universe-title-parent"]).to_string()).bind(head).execute(&store.pool).await.unwrap();let snapshot=store.universe_catalogue_snapshot().await.unwrap();let source=snapshot.universes.iter().find(|u|u.project_id==root.id).unwrap();assert!(source.catalogue.is_none());assert!(source.unavailable.as_ref().unwrap().contains("parent"));let notes=store.universe_notes_snapshot(&novel.project.id).await.unwrap();assert!(notes.planning.is_none());assert!(notes.universe.is_none());
}
#[tokio::test]
async fn concurrent_catalogue_changes_keep_series_membership_and_source_in_one_snapshot(){
    let (dir,store,root,novel)=fixture().await;let writer=Storage::open(&dir.path().join("universe.sqlite")).await.unwrap();let source=store.save_project_data(&root.id,"planning",planning(),None).await.unwrap();let pid=novel.project.id.clone();let uid=root.id.clone();let writer_task=tokio::spawn(async move{let mut saved=writer.load_project_data(&uid,"universeCatalogue").await.unwrap().unwrap();for i in 0..24{let mut payload=saved.payload;payload["novels"][0]["seriesId"]=if i%2==0{Value::Null}else{json!("series")};saved=writer.save_project_data(&uid,"universeCatalogue",payload,Some(saved.revision_id)).await.unwrap();}writer.close().await;});
    for _ in 0..32{let notes=store.universe_notes_snapshot(&pid).await.unwrap();assert!(notes.unavailable.is_none());let universe=notes.universe.unwrap();let membership=universe.catalogue.unwrap().novels.into_iter().find(|n|n.project_id==pid).unwrap();assert_eq!(notes.membership.series_id,membership.series_id);assert_eq!(notes.membership.universe_id.as_deref(),Some(root.id.as_str()));assert_eq!(notes.planning.as_ref().unwrap().revision_id,source.revision_id);}
    writer_task.await.unwrap();assert!(store.load_project_data(&pid,"planning").await.unwrap().is_none());
}
